import React, { useState, useMemo } from 'react';
import './App.css';

// importo de los componentees que pide y que he creado 
import Cabecera from './componentes/Cabecera';
import MenuNavegacion from './componentes/MenuNavegacion';
import EscaparateProductos from './componentes/EscaparateProductos';
import FormularioNuevosProductos from './componentes/FormularioNuevosProductos';
import Pie from './componentes/Pie';
import Carrito from './componentes/Carrito';


function App() {
  const [productos, setProductos] = useState(inventario);
  const [carrito, setCarrito] = useState(new Map());

  return (
    <div className="container">
      <Cabecera titulo="Tienda de mascotas" />
      <MenuNavegacion />
      <EscaparateProductos 
        productos={productos} 
        carrito={carrito} 
        setCarrito={setCarrito} 
        maxCopias={MAX_COPIAS} 
        divisa={DIVISA} 
      />
      <FormularioNuevosProductos setProductos={setProductos} />
      <Carrito carrito={carrito} divisa={DIVISA} />
      <Pie contenido="© 2026 Mi Tienda" />
    </div>
  );
}

export default App;
